import type { CSSProperties, ReactNode } from 'react';
import './image-shutter-reveal.css';

export interface ImageShutterRevealProps {
  /** The image. Give it its own alternative text. */
  children: ReactNode;
  /** Number of shutter slats. */
  slats?: number;
  /** Delay between slats, in milliseconds. */
  stagger?: number;
  /** Change this value to close and reopen the shutters. */
  playKey?: number | string;
  className?: string;
}

/**
 * Vertical slats fold away one after another to expose the image beneath.
 * The image is in the page the whole time, so its alt text is always there.
 */
export function ImageShutterReveal({
  children,
  slats = 6,
  stagger = 90,
  playKey = 0,
  className = '',
}: ImageShutterRevealProps) {
  return (
    <figure className={`mg-shutter ${className}`}>
      {children}
      <div key={playKey} className='mg-shutter__slats' aria-hidden='true'>
        {Array.from({ length: slats }, (_, index) => (
          <span
            key={index}
            className='mg-shutter__slat'
            style={{ '--mg-delay': `${index * stagger}ms` } as CSSProperties}
          />
        ))}
      </div>
    </figure>
  );
}

.mg-shutter {
  position: relative;
  margin: 0;
  overflow: hidden;
  border-radius: 14px;
}

.mg-shutter > :first-child {
  display: block;
  width: 100%;
  height: auto;
}

.mg-shutter__slats {
  position: absolute;
  inset: 0;
  display: flex;
  pointer-events: none;
}

.mg-shutter__slat {
  flex: 1;
  background: var(--mg-ink, #0c1738);
  /* Slight overlap hides hairline gaps between slats. */
  margin-right: -1px;
  transform-origin: left center;
  animation: mg-shutter-open 520ms cubic-bezier(0.6, 0, 0.2, 1) forwards;
  animation-delay: calc(200ms + var(--mg-delay));
}

.mg-shutter__slat:nth-child(even) {
  background: var(--mg-accent, #164cff);
}

@keyframes mg-shutter-open {
  to {
    transform: scaleX(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-shutter__slats {
    display: none;
  }
}
